\label{thm: main forward}
Let $L \subseteq \mathrm{Mat}_{n \times m}$ be a two-dimensional linear space of matrices, and let $Y_L \subseteq \mathrm{Gr}(n, n+m)$ be its Schubert variety. Then:
\begin{enumerate}
\item $Y_L$ is normal with quotient singularities (see \Cref{thm: rational singularities});
\item the degree of $Y_L$ in the Pl\"{u}cker embedding is computed in \Cref{theorem: degree of YL};
\item the Schubert class of $\operatorname{\mathnormal{Y_L}}$ in the Chow ring of $\mathrm{Gr}(n,n+m)$ is computed in \Cref{thm: schubert class};
\item the intersection cohomology ring of $Y_L$ is completely described in \Cref{thm: intersections general};
\item the ideal of $Y_L$ in the Pl\"{u}cker embedding is generated in degree $2$ (see \Cref{thm: quadratic generation});
\item the ideal of $Y_L$ satisfies Green's property $N_p$ in the range given in \Cref{corol: Np property}.
\end{enumerate}

\label{ex:quadric-surface}
Consider the pencil 
\[
L=J_1(x_1)\boxplus J_1(x_2) =
\left\{
{\footnotesize \begin{pmatrix}
x_1&0\\
0&x_2
\end{pmatrix} }
\mid x_1,x_2\in \mathbb{C}
\right\} \subseteq V^* \otimes W
\]
with $\dim V = \dim W = 2$. This is the linear space parameterised by a generic tensor in $\mathbb{C}^2 \otimes \mathbb{C}^2 \otimes \mathbb{C}^2$. The open embedding of $L$ in $\mathrm{Gr}(2,V\oplus W)$ is defined by 
\[ (x_1,x_2) \mapsto {\footnotesize \begin{pmatrix}
1 & 0 & x_1&0\\
0 & 1 & 0&x_2
\end{pmatrix}} , 
\] 
which in the Pl\"ucker coordinates is given by to $\varphi(x_1,x_2) = [1:x_1:x_2:x_1x_2]$; therefore $Y_L$ is the quadric surface in $\mathbb{P}^3$. The map $\varphi$ extends to a rational map $\mathbb{P}^2 \dashrightarrow \mathbb{P}^3$ with $\varphi([x_0:x_1:x_2]) = [x_0^2 :x_0x_1:x_0x_2:x_1x_2]$ whose indeterminacy locus is the set $Z = \{ [0,1,0], [0,0,1] \}$. The resolution of this map blows-up the two points, making the line spanned by them  into a $(-1)$-curve. The quadric is the result of the contraction of that $(-1)$-curve to a point. This gives the classical isomorphism between the blow-up of $\mathbb{P}^2$ at two points and the blow-up of $\mathbb{P}^1 \times \mathbb{P}^1$ at one point. 

More generally, for the pencil $L=J_1(x_1)^{\boxplus e_1}\boxplus J_1(x_2)^{\boxplus e_2}$, the Schubert variety of $L$ is again $\mathbb{P}^1\times\mathbb{P}^1$, and the Pl\"ucker embedding of $\mathrm{Gr}(e_1+e_2, 2(e_1+e_2))$ restricts to the embedding given by $\mathcal{O}_{\mathbb{P}^1 \times \mathbb{P}^1} (e_1,e_2)$. In this case $Y_L$ is a Segre-Veronese variety. These varieties will appear in case (1)(ii) of \Cref{prop: smooth YL}.

\label{ex: length 2 scheme}
Consider the pencil
\[
L=J_2(x_1)
=
\left\{
{\footnotesize \begin{pmatrix}
x_1 & x_2\\
0   & x_1
\end{pmatrix} }
\mid x_1,x_2\in \mathbb{C}
\right\}.
\]
with $\dim V = \dim W = 2$. When regarded as a tensor in $\mathbb{C}^2 \otimes \mathbb{C}^2 \otimes \mathbb{C}^2$, this is a general tangent vector to the Segre variety. The rational map $\varphi: \mathbb{P}^2 \dashrightarrow \mathbb{P}^3$ is defined by $\varphi([x_0:x_1:x_2]) = [x_0^2 : x_0x_1 : x_0x_2 : x_1^2]$. The indeterminacy locus of $\varphi$ is a scheme of length $2$ supported at the point $[0,0,1]$ and contained in the line at infinity $x_0=0$. The Schubert variety $Y_L$ is the quadric cone in $\mathbb{P}^3$. The resolution of $\varphi$ will be studied, in a more general setting, in \Cref{subsec: smooth resolution}: the exceptional locus is a chain of two curves, with self-intersection $(-2)$ and $(-1)$. The blow-up procedure makes the line at infinity into a $(-1)$-curve. The surface $Y_L$ is the result of the contraction of the exceptional $(-2)$-curve, resulting in the $\mathsf{A}_1$-singularity at the vertex of the cone, and of the line at infinity, resulting in a smooth point.

More generally, if $L = J_k(x_1)$ consists of a single Jordan block, then the indeterminacy locus of the rational map is a local scheme $Z$ with ideal $I(Z) = (x_0,x_1^k)$. In this case, the exceptional locus of the resolution of $\varphi$ is a chain of $k$ curves with self-intersection $(-2), \ldots, (-2), (-1)$. The line at infinity lifts to a curve with self-intersection $-(k-1)$. The surface $Y_L$ is obtained by the contraction of all exceptional $(-2)$-curves, resulting in the $\mathsf{A}_{k-1}$-singularity, and the contraction of the strict transform of the line at infinity, resulting in a singularity of type $\frac{1}{k-1}(1,1)$. When $k = 2,3$, this falls into case (1) of \Cref{prop: reconstruct case by case}, and if $k > 3$, it falls into case (1) of \Cref{prop: W non DuVal singularity}.

\label{notation:pencils}
    The pencil $L$ has a unique decomposition into a left-singular component, a right-singular component and a regular component: $L =  S^{\mathrm{left}}_\bullet \boxplus S^{\mathrm{right}}_\bullet \boxplus L^{\mathrm{reg}}_\bullet$. Let $\epsilon_{\#}$ and $\eta_{\#}$ be the number of left and right singular blocks, respectively. Let $\boldsymbol{\epsilon} = (\epsilon_1  , \dots ,  \epsilon_{\epsilon_{\#}})$ and $\boldsymbol{\eta}= (\eta_1,\ldots, \eta_{\eta_{\#}})$ be the left and right singular Kronecker invariants of $L$. In particular
    \[
    S^{\mathrm{left}}_\bullet = S^{\mathrm{left}}_{\epsilon_1} \boxplus \ldots \boxplus S^{\mathrm{left}}_{\epsilon_{\epsilon_{\#}}}, \qquad
    S^{\mathrm{right}}_\bullet = S^{\mathrm{right}}_{\eta_1} \boxplus \ldots \boxplus S^{\mathrm{right}}_{\eta_{\eta_{\#}}}.
    \]
    Let $\epsilon_\bullet = \sum \epsilon_i$ be the number of rows of $S^{\mathrm{left}}_{\bullet}$ and $\eta_\bullet = \sum \eta_i$ for the number of columns of $S^{\mathrm{right}}_\bullet$. Let $n_0= \epsilon_\bullet + \eta_\bullet + \eta_{\#}$ and $m_0 = \epsilon_\bullet + \epsilon_{\#} + \eta_\bullet$ be the number of rows and columns of the singular components. 

    Let $\theta_1, \ldots , \theta_s \in \mathbb C[x_1,x_2]_1$ be the $s$ distinct generalised eigenvalues of $L$: we may assume they have the form $\theta_i = x_1 - \zeta_ix_2$ for distinct $\zeta_i \in \mathbb{C}$. For every $i \in [s]$, set:
    \begin{itemize}
    \item $k_{i  1} < \ldots < k_{i  h_i}$ the distinct sizes of the Jordan blocks $J_{k_{i 1}}(\theta_i), \ldots , J_{k_{i \, h_i}}(\theta_i)$;
    \item $e_{i ,j} \geq 1$ the number of blocks $J_{k_{i j}}(\theta_i)$;
    \item $d_i := e_{i 1} + \ldots + e_{i h_i}$ the total number of Jordan blocks with eigenvalue $\theta_i$;
    \item $L_i := J_{k_{i 1}}(\theta_i)^{\boxplus e_{i 1}}\boxplus \ldots \boxplus J_{k_{i \, h_i}}(\theta_i)^{\boxplus e_{i h_i}}$ the sum of Jordan blocks with eigenvalue $\theta_i$;
    \item $n_i := e_{i 1}k_{i 1} + \ldots + e_{i h_i}k_{i \, h_i}$ be the size of $L_{i}$;
    \item $X_i := L(\zeta_i,1)$ the rank degenerate matrix at the value $\zeta_i$ with $\theta_i(\zeta_i,1) = 0$;
    \item $Z_i\subseteq \mathbb P^2=\mathbb P(\mathbb{C} \oplus L)$ the $0$-dimensional scheme supported at $[0:X_i]$ defined by the system of maximal minors of the matrix $D_{n_i}([x_0 I_{n_i} | L_i(x_1,x_2)])$.
    \end{itemize}

\label{prop: image of phi} 
The following holds:
\begin{enumerate}[leftmargin=*]
\item\label{prop: image of phi regular} 
If $L$ is a regular pencil, then the image of $\varphi|_{H_\infty}$ is the point $[W]\in \mathrm{Gr}(n,V\oplus W)$. In particular, $[W] \in \operatorname{\mathnormal{Y_L}}$.
\item\label{prop: image of phi mixed}
If $L$ is a singular pencil with left and right singular invariants $\boldsymbol{\epsilon}$ and $\boldsymbol{\eta}$ respectively. Then the image of $\varphi|_{H_\infty}: H_\infty \to \operatorname{\mathnormal{Y_L}}$ in the Pl\"ucker embedding of $\mathrm{Gr}(n,V \oplus W)$ is a rational normal curve $C_\infty$ of degree $\epsilon_\bullet + \eta_\bullet$.
\end{enumerate}

\label{prop: W singularity}
Let $L=L_{1}\boxplus \ldots \boxplus L_{s}$ be a regular pencil of size $n$, with $L_{i}$ of size $n_i=\sum_{j \in [h_i]} e_{ij}k_{ij}$. Let $\kappa := \sum_{i \in [s]} k_{i \, h_{i}}$ be the sum of the maximal sizes of Jordan blocks, one for each eigenvalue. Then, the following holds: 
\begin{enumerate}
    \item[$(i)$] the tangent cone $\mathrm{TC}_{[W]}Y_L$ is a cone over a rational normal curve of degree $\kappa - 1$; \vspace{1ex}
    \item[$(ii)$] $[W]$ is a smooth point of $Y_L$ if and only if $\kappa = 2$; \vspace{1ex}
    \item[$(iii)$] if $\kappa \geq 3$, then $Y_L$ has a quotient singularity at $[W]$ of type $\frac{1}{\kappa -1}(1,1)$; \vspace{1ex}
    \item[$(iv)$] the map $\psi$ is well defined, regular and it coincides with the $(\kappa-1)$-th Veronese embedding of $H_\infty$ onto $\mathbb{P} T_{[W]} Y_L$.
\end{enumerate}

\label{lemma: transform one point}
    Let $I = \prod_{i \in [h]} (x_0,x_1^{k_i})^{e_i}$. Then, the weak transform of $I$ after the $\ell$-th blow-up is supported at $z_\ell$ and it is the ideal
    \[
   I_\ell = \prod_{\{ j \mid k_j > \ell \}}(\widetilde{x}_0 , \widetilde{x}_1^{k_j-\ell})^{e_j}
    \]
    where $\widetilde{x}_0$ and $\widetilde{x}_1$ are the local coordinates at $z_\ell$ of the strict transform of $H_\infty$ and the exceptional divisor of the $\ell$-th blow-up, respectively. In particular, the order of vanishing of $I_\ell$ at $z_\ell$ is $\mu_{\ell+1}$, and if $\ell \geq k_h$, then $I_\ell$ is the unit ideal.

\label{prop: contraction and embeddings}
    For $i\in [s]$, let $\ell \leq k_{h_i}$ be an integer. 
    \begin{itemize}
    \item If $\ell = k_{i j}$ for some $j$, then $\widetilde{\varphi}$ maps the exceptional divisor $A_{i \ell}$ to a rational normal curve of degree $e_{i j}$.
    \item If $k_{i j} < \ell < k_{i \, j+1}$, then $\widetilde{\varphi}$ contracts $A_{i \ell}$ to a point.
    \end{itemize}

Suppress $i$ from the notation. Let $k_1  , \dots ,  k_h$, $e_1  , \dots ,  e_h$ be the relevant regular invariants. Let $n' = n - \eta_{\#}$. For $\ell \in [k_h]$, let $E_\ell$ be the total transform in $\widetilde{X}$ of the $\ell$-th exceptional divisor; in particular $E_\ell = A_\ell + \cdots + A_{k_h}$.

    By \Cref{prop: resolution of phi}, the map $\widetilde{\varphi}$ is given by the complete linear series of the divisor $D = (n-\eta_\#)\widetilde{H} - \sum_{j \in [k_h]} \mu_{j} E_j$. From the intersection products in \Cref{lemma: intersections upstairs} we have
    \begin{align*}
        [A_{\ell}]\cdot [D] & = - \sum_{j \in [k_h]}  \mu_j [A_\ell]\cdot [E_j] = \mu_\ell - \mu_{\ell+1} = \begin{cases}
           e_{h'} &  \text{if } \ell = k_{h'} \text{ for some $h'$} \\
            0 & \text{otherwise}.
        \end{cases}
    \end{align*}
 Therefore, the image of $\widetilde{\varphi}|_{A_\ell}$ is a point if $k_{h'}< \ell < k_{h'+1}$, and it is a curve of degree $e_{j}$ if $\ell = k_j$. We show that in the latter case it is the rational normal curve of degree $e_j$. This is equivalent to showing that $A_{k_j}$ is mapped by the complete linear series of degree $e_j$. 

Let $X$ and $X'$ be respectively the $(\ell-1)$-th and the $\ell$-th blow-up in the considered chain. Let $z \in X$ be the center of the blow-up, and $A'$ the exceptional divisor. So $\pi: X' \to X$ maps $A'$ to $z$ and $A_\ell$ is the strict transform of $A'$ after the subsequent blow-ups. Abusing notation, let $\varphi : X \dashrightarrow Y_L$ be the rational map extended to $X$ and $\varphi' : X' \dashrightarrow Y_L$ its extension to $X'$. 

The base ideal of $\varphi$ is $I = \prod_{\{j' \mid \ell \leq k_{j'} \}} (x_0,x_1^{k_{j'} - \ell+1})^{e_{j'}}$. By \Cref{lemma: transform one point}, $I$ has multiplicity $\mu_\ell$ at $z$: therefore, the linear series of $\varphi'$ restricted to $A'$ is given by $(I \cap \mathfrak{m}^{\mu_\ell}) / (I \cap \mathfrak{m}^{\mu_\ell+1})$ where $\mathfrak{m}$ is the maximal ideal supported at $z$. If $\ell = k_j$, then $I= (x_0,x_1)^{e_j} \cdot \prod_{\{j' \mid \ell < k_{j'}\}} (x_0,x_1^{k_{j'} - \ell+1})^{e_{j'}}$. So the component of degree $\mu_\ell$ is $x_0^{\mu_{\ell+1}} \cdot \mathbb{C}[x_0,x_1]_{e_j}$, which is the complete linear series of degree $e_j$ on $A' \simeq \mathbb{P}^1$.

\label{thm: intersections general}
Let $L = L_{\mathrm{sing}} \boxplus L_1 \boxplus \ldots \boxplus L_s$ be a pencil with $s$ regular components with distinct eigenvalues $\theta_1  , \dots ,  \theta_s$. For $i \in [s]$, let $k_{i 1} < \ldots < k_{i {h_i}}$ be the distinct sizes of the Jordan blocks with eigenvalue $\theta_i$. Then $\mathrm{N}^1_\mathbb{Q}(Y_L)$ is generated by the classes $\zeta$ and $\gamma_{ij}$ for $i \in [s]$ and $j \in [h_i]$. The intersection pairing is given as follows:
\begin{enumerate}
\item\label{item: products between different chains} for any two $i_1,i_2$ distinct, with $(j_1,j_2) \neq (h_{i_1},h_{i_2})$, we have
\[
\gamma_{i_1 j_1} \cdot \gamma_{i_2 j_2} = 0.
\]
\item\label{item: products along a chain} for every $i = 1  , \dots ,  s$ and every $(j_1,j_2) \neq (h_i,h_i)$, we have 
    \begin{align*}
    \zeta \cdot \gamma_{ij} & = 0 \text{ for every $j < h_i$} \\
    \gamma_{i j_1} \cdot \gamma_{i j_2} & = \begin{cases}
        - \frac{1}{k_{i j_1} - k_{i  j_1-1}} - \frac{1}{k_{i  j_1+1} - k_{i \, j_1}} & \text{if  $j_1=j_2$}  \\
        \frac{1}{k_{i \, j_1+1} - k_{i \, j_1}} & \text{if $j_2 = j_1+1$}\\
        0 & \text{if  $|j_1-j_2| > 1$}
        \end{cases}
\end{align*}
\item\label{item: products singular case} If $L$ is a singular pencil, then 
\[
\begin{array}{l}
    \zeta^2 = 1 \\
    \zeta \cdot \gamma_{i \, h_i} = 0
\end{array} \qquad \qquad 
\begin{array}{ll}
 \gamma_{i \, h_i}^2 =  - \frac{1}{k_{i \, h_i} - k_{i \, h_i-1}} \\
 \gamma_{i_1 h_{i_1}} \cdot \gamma_{i_2 h_{i_2}} = 0 & \text{ if $i_1 \neq i_2$}
\end{array}
\]
and
\[
[C_\infty] = \zeta - \textstyle  \sum_{i\in [s]} \sum_{j \in [h_i]} k_{i j} \gamma_{ij}.
\]
\item\label{item: products regular case} If $L$ is a regular pencil, given $\kappa := \sum_{i=1}^s k_{i \, h_i}$, then 
\[
\begin{array}{l}
    \zeta^2 = \frac{\kappa}{\kappa - 1} \\
    \zeta \cdot \gamma_{i \, h_i} = \frac{1}{\kappa -1 }
\end{array} \qquad \qquad 
\begin{array}{ll}
 \gamma_{i \, h_i}^2 = - \frac{1}{k_{i \, h_i} - k_{i \, h_i-1}} + \frac{1}{\kappa -1} \\
 \gamma_{i_1 h_{i_1}} \cdot \gamma_{i_2 h_{i_2}} = \frac{1}{\kappa -1} & \text{ if $i_1 \neq i_2$}
\end{array}
\]
and
\[
\zeta= \textstyle  \sum_{i\in [s]} \sum_{j \in [h_i]} k_{i j} \gamma_{ij}.
\]
\end{enumerate}

\label{lemma: mumford pullback of type A singularity}
Let $\widetilde{S}$ be a smooth surface, let $S$ be a normal surface and let $f:\widetilde{S} \to S$ be the contraction of a chain of $(-2)$-curves $E_1 \cup \ldots \cup E_{d-1}$ to a point $p \in S$. Let $C \subset S$ be a smooth curve passing through $p$ such that its strict transform $\widetilde{C} = \overline{f^{-1}(C\setminus \{p\})}$ intersects either $E_1$ or $E_{d-1}$. Then the coefficients of the pullback ${\textstyle f^\ast C = \widetilde{C} + \sum_{i \in [d-1]} c_i E_i}$ are
\begin{align*}
    c_i = \begin{cases}
    \frac{d-i}{d} & \text{if $\widetilde{C}$  intersects $E_1$} \\
    \frac{i}{d} & \text{if $\widetilde{C}$ intersects $E_{d-1}$} .
    \end{cases}
\end{align*}

\label{corol: uniqueness exceptional curves}
Let $C_{ij} \subseteq Y_L$ be the rational normal curve as defined in \ref{eqn: CijCurves}. Then the following holds:
\begin{itemize}
\item If $L$ is a singular pencil, then $C_{ij}$ is the unique irreducible curve representing the class $\gamma_{ij} = [C_{ij}] \in \mathrm{N}^1_{\mathbb{Q}}(Y_L)$.
\item If $L$ is a regular pencil and $j < h_i$, then $C_{ij}$ is the unique irreducible curve representing the class $\gamma_{ij} = [C_{ij}] \in \mathrm{N}^1_{\mathbb{Q}}(Y_L)$. 
\item If $L$ is regular and $j = h_i$, then $C_{i \, h_i}$ is the unique irreducible curve representing the class $\gamma_{i \, h_i} = [C_{i \, h_i}] \in \mathrm{N}^1_\mathbb{Q}(Y_L)$ and passing through $[W]$.
\end{itemize}

\label{prop: W non DuVal singularity}
Let $L$ be a pencil of size $n$. Assume $Y_L$ has a singular point $q_W$ that is a quotient singularity of type $\frac{1}{\kappa -1} (1,1)$ not of Du Val type. Then $\kappa \geq 4$, $L$ is regular and one of the following holds: \vspace{1ex}
\begin{enumerate}[leftmargin=*]
\item There are no non-positive curves passing through $q_W$. Then $L$ has a single eigenvalue, and there is an integer $e$ such that $\kappa e = n$ and $L = J_\kappa(x_1)^{\boxplus e}$. \vspace{1ex}
\item There are exactly $s$ non-positive curves $D_1  , \dots ,  D_s$ passing through $q_W$. In this case $L$ has exactly $s$ distinct eigenvalues $\theta_1  , \dots ,  \theta_s$; up to reordering, the configuration $(\theta_1  , \dots ,  \theta_s)$ in $\mathbb{P}^1$ is $\mathrm{GL}_2$-equivalent to the configuration of the tangent lines $T_{q_W}D_1  , \dots ,  T_{q_W}D_s$ in $\mathbb{P}(\mathrm{TC}_{[W]}Y_L)$, which is a rational normal curve of degree $\kappa-1$. Moreover, for every $i \in [s]$, $D_i$ is connected to a chain of $h_i-1$ other negative curves, $C_{i1}, \ldots, C_{i \, h_i-1}, C_{i \, h_i}=D_i$. Let $e_{ij} = \deg C_{ij}$ and $c_{ij} = [C_{ij}]^2$. Define recursively 
\begin{align*}
u_{i \, h_i} := {\textstyle \frac{1}{\kappa-1}} - c_{i \, h_i}  \quad , \quad u_{ij} := - c_{ij} - u_{i \, j+1} 
\end{align*}
and set $k_{i j} := \sum_{\ell=1}^{j} \frac{1}{u_{i \ell}}$. Then $k_{i j}$ are integers and for $L = L_1 \boxplus \ldots \boxplus L_s$, we have
\[
L_i = J_{k_{i 1}}(\theta_i)^{\boxplus e_{i 1}} \boxplus J_{k_{i 2}}(\theta_i)^{\boxplus e_{i 2}} \boxplus \ldots \boxplus J_{k_{i \, h_i}}(\theta_i)^{\boxplus e_{i h_i}}.
\]
\end{enumerate}

\label{prop: Cinfty very negative}
Let $L$ be a pencil of size $n$. Assume $Y_L$ has a negative curve $C_\infty$ with self-intersection $1-\kappa < -2$. Then $\kappa \geq 4$, and $L$ is singular. There are exactly $s$ negative curves $D_1  , \dots ,  D_s$ intersecting $C_\infty$. In this case the regular component $L^{\mathrm{reg}}$ of $L$ has exactly $s$ distinct eigenvalues $\theta_1  , \dots ,  \theta_s$. The configuration $(\theta_1  , \dots ,  \theta_s)$ in $\mathbb{P}^1$ is $\mathrm{GL}_2$-equivalent to the configuration of intersection points $(D_i \cap C_\infty : i \in [s])$ on $C_\infty$.  Moreover, for every $i \in [s]$, $D_i$ is connected to a chain of $h_i-1$ other negative curves, $C_{i1}, \ldots , C_{i \, h_i-1}, C_{i \, h_i} = D_i$. Let $e_{ij} = \deg C_{ij}$ and $c_{ij} = [C_{ij}]^2$. Define recursively 
\begin{align*}
u_{i \, h_i} :=  
- c_{i \, h_i}  \quad , \quad u_{ij} := - c_{ij} - u_{i \, j+1} 
\end{align*}
and set $k_{i j} := \sum_{\ell=1}^{j} \frac{1}{u_{i \ell}}$. Then $k_{i j}$ are integer and for $L^{\mathrm{reg}} = L_1 \boxplus \ldots \boxplus L_s$, we have
\[
L_i = J_{k_{i 1}}(\theta_i)^{\boxplus e_{i 1}} \boxplus J_{k_{i 2}}(\theta_i)^{\boxplus e_{i 2}} \boxplus \ldots \boxplus J_{k_{i \, h_i}}(\theta_i)^{\boxplus e_{i h_i}}.
\]

\label{prop: reconstruct case by case}
Let $L$ be a pencil of size $n$. Assume $Y_L$ is singular with only Du Val singularities and it has no curves $C$ with $C^2 < -2$. Then $Y_L$ has at most three negative curves and one of the following occurs:
\begin{enumerate}[leftmargin=*]
\item $Y_L$ has no negative curves. Then $L$ is regular, has a unique eigenvalue, and the singularities determine the structure of the Jordan blocks:
\begin{center}
\vspace{1ex}
{\small \begin{tabular}{c|c}
    singularities &  Jordan sizes and multiplicities \\ \hline
    one $\mathsf{A}_1$ point &   $(k_1^{e_1}) = (2^{n/2})$ \\ 
    one $\mathsf{A}_1$ point and one $\mathsf{A}_2$ point  &  $(k_1^{e_1}) = (3^{n/3})$
\end{tabular} }
\vspace{1ex}
\end{center}
~
\item $Y_L$ has exactly one negative curve $D$. Then $L$ is regular, and the self-intersection of the unique negative curve determines the structure of the Jordan blocks as follows
\begin{center}
\vspace{1ex}
{\small \begin{tabular}{c|c|c}
    $D^2$ &  $\deg D$ & Jordan sizes and multiplicities \\ \hline
    $-3/2$ &  $e_1$ & $(k_1^{e_1},k_2^{e_2}) = (2^{e_1}, 3^{\frac{1}{3} (n - e_1)})$ \\
    $-1/2$ &  $e_{1,1}$ & $[(k_{1,1}^{e_{1,1}}), (k_{2,1}^{e_{2,1}})] = [(2^{e_{1,1}}), (1^{n-2e_{1,1}})]$ 
\end{tabular} }
\vspace{1ex}
\end{center}
~
\item $Y_L$ has exactly two negative curves $D_1,D_2$. Then the self-intersections and the degrees of the negative curves determine the structure of the Jordan blocks as follows
\begin{center}
\vspace{1ex}
{\small \begin{tabular}{c|c|c|c}
    $(D_1^2,D_2^2)$ &  $(\deg D_1,\deg D_2)$ & type & Jordan sizes and multiplicities \\ \hline
    $(-1/2, -1)$ & $(e,e')$ & singular & $(k_{1}^{e_1}) = (2^{e})$ \\
    $(-1/3, -2)$ & $(e,e')$ & singular & $(k_{1}^{e_1}) = (3^{e})$ \\
    $(-3/2, -1/2)$ & $(e_1,e_2)$ & regular& $ (k_1^{e_1},k_2^{e_2}) = (2^{e_1}, 3^{e_2})$ 
\end{tabular} }
\vspace{1ex}
\end{center}
~
\item $Y_L$ has exactly three negative curves $D_1,D_2,D_3$ forming a chain $(D_1,D_2,D_3)$. Then $L$ has exactly two eigenvalues and the self-intersections and the degrees of the negative curves determine the structure of the Jordan blocks as follows:
\begin{center}
\vspace{1ex}
{\small \begin{tabular}{c|c|c|c}
    $(D_1^2,D_2^2,D_3^2)$ &  $(\deg D_i, i \in [3])$ & type & Jordan sizes and multiplicities \\ \hline
    $(-3/2, -1/2, -2)$ & $(e_1,e_2,e')$ & singular & $(k_1^{e_1},k_2^{e_2}) = (1^{e_1}, 2^{e_2})$ \\ 
    $(-3/2, -1, -2)$ & $(e_1,e_2,e')$ & singular & $(k_1^{e_1},k_2^{e_2}) = (2^{e_1}, 3^{e_2})$ \\
    $(-1/2, -2, -1)$ & $(e_{1,1},e_{2,1},e')$ & singular & $[(k_{1,1}^{e_{1,1}}), (k_{2,1}^{e_{2,1}})] = [(2^{e_{1,1}}) , (1^{e_{2,1}})]$ \\
