~
\item $Y_L$ has exactly three negative curves $D_1,D_2,D_3$ all intersecting at the same point. Let $e_i = \deg D_i$. Then $L$ is regular with 
\[
L = J_1(x_1)^{\boxplus e_1} \boxplus J_1(x_1+x_2)^{\boxplus e_2} \boxplus J_1(x_1 + 2x_2)^{\boxplus e_3}.
\]
\end{enumerate}

\label{prop: hyperplane cut YL}
A generic hyperplane section of $Y_L$ is an irreducible, linearly normal, smooth curve $C$ with 
\begin{align*}
\deg(C) = \textstyle (n-\eta_{\#})^2 - \sum_{i,j} \mu_{ij}^2 \quad \text{ and } \quad g(C) = \textstyle  \binom{n-\eta_{\#}-1}{2} - \sum_{i,j} \binom{\mu_{ij}}{2}.
\end{align*}
